effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  float rad = radians(angle);
  vec2 dir = vec2(cos(rad), sin(rad));
  vec2 rdir = normalize(uv - 0.5 + 1e-5);
  dir = normalize(mix(dir, rdir, radial) + 1e-5);
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = src.a;
  float amt = amount * mixAmt;
  float r = texture2DCv(inputImg.texture, uv + dir * amt).r;
  float g = src.g;
  float b = texture2DCv(inputImg.texture, uv - dir * amt).b;
  gl_FragColor = vec4(r, g, b, a);
}
